INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Номенклатура Эй Джи Групп счет УТ-68 13.10 в загрузку 1С', 'Правило «Создание номенклатуры в 1С через OData». Счёт ООО «Эй Джи Групп» № УТ-68 от 13.10.2026 + вес из «ЛОТ 1 Самолет+капсула» (листы кухня, посуда, Ванная, Остатки капсулы). 47 строк как в счёте. Колонки: Артикул (как в колонке счёта, текстом), Штрихкод (пусто), Наименование (как в счёте), Количество 1, Вес из сертификата (из лота, кг; посуда — за комплект), ТН ВЭД, Вид номенклатуры, Бренд — пусто. Сопоставление: посуда и капсулы — по артикулу, кухня и ванная — по описанию. Вес найден у всех 47.', '/converted/nomenklatura-ej-dzhi-grupp-schet-ut-68-13-10-v-zagruzku-1c.xlsx', 'Номенклатура Эй Джи Групп счет УТ-68 13.10 в загрузку 1С.xlsx', 'converted/nomenklatura-ej-dzhi-grupp-schet-ut-68-13-10-v-zagruzku-1c.xlsx', 8258);